import{_ as s,l as n,o as e,c as o,v as i,p as l,x as r,d as p,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"不等间隔采样","description":"","frontmatter":{"title":"不等间隔采样","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/irregular-sampling.md","filePath":"quant/irregular-sampling.md","lastUpdated":1789023840000}'),d={name:"quant/irregular-sampling.md"};function A(u,a,c,B,m,_){const t=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="不等间隔采样" tabindex="-1">不等间隔采样 <a class="header-anchor" href="#不等间隔采样" aria-label="Permalink to &quot;不等间隔采样&quot;">​</a></h1><div class="epigraph"><p>成交发生在随机时点上；若用上一笔价格填进日历网格，看起来得到了等间隔序列，却额外制造了零收益与滞后相关。</p><footer>—— 高频计量中 previous-tick 插值与 refresh time 的标准处理；久期一侧见 Engle and Russell, Autoregressive Conditional Duration, Econometrica 1998</footer></div><p><a href="/quant/rv-noise">上一课</a>写无噪声时 RV 一致估积分波动，有 i.i.d. 噪声时偏差 \\(2n\\sigma_\\varepsilon^2\\)；先清洗与异常处理，再谈 TSRV、已实现核与预平均。教科书里的收益是等间隔，交易所里的观测是点过程。缺口是采样方案本身：日历网格、事件时钟、多资产对时，都会改变噪声的表观与已实现协方差的偏差。本课写采样，不重推核带宽。插值不是中性操作；「一分钟线」已经是某种聚合产品。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单资产时，日历时间采样（每 \\(\\Delta\\) 取一个价格）与事件时间采样（每笔、每 \\(k\\) 笔、每 \\(V\\) 成交量）给出不同的序列。日历采样在开盘密集、午后稀疏：同样 \\(\\Delta\\)，信息含量不同。事件采样在信息到达时自动加密，与 <a href="/quant/vpin">VPIN</a> 的成交量时钟同类，但若每笔都用，噪声项 \\(2n\\sigma_\\varepsilon^2\\) 里的 \\(n\\) 变成随机且与波动相关——繁忙时噪声贡献更大。</p><p>多资产更严重。股票 A 与 B 很少在同一毫秒成交。要算 \\(\\sum r^A r^B\\)，必须先定义同步价格。用 previous-tick：在网格点 \\(t_i\\) 取各资产「不超过 \\(t_i\\) 的最后一笔」。稀薄的一方会反复使用过时价格，制造零收益，压低已实现协方差，这就是 <strong>Epps 效应</strong> 的一个机械来源：采样越密，表观相关越低。问题不是「要不要高频」，而是高频下必须声明对时规则。</p><h3 id="插值不是中性操作" tabindex="-1">插值不是中性操作 <a class="header-anchor" href="#插值不是中性操作" aria-label="Permalink to &quot;插值不是中性操作&quot;">​</a></h3><p>线性插值在两个成交之间画直线，等于把未来成交价的信息提前写进当前网格——前视，回测非法，估计里制造虚假的平滑、\\(IV\\) 偏低。Next-tick 同样前视。Previous-tick 因果，但引入交错误差（stale price）。没有无代价的同步。选择取决于对象：执行轨迹应用因果；事后估协方差可以考虑 Hayashi–Yoshida，它避免网格。</p><p><span class="marginnote">「一分钟线」通常已经是某种插值或最后一笔聚合的产品，不是原始点过程。用分钟线估噪声修正 RV，等于在数据商的采样规则之上再套一层理论。应尽量回到 tick，自己选网格；若只能用分钟线，把聚合规则当作模型的一部分写进报告。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>日历网格 + previous-tick。</strong> 实现简单，与五分钟 RV 兼容。应丢掉没有新成交的网格点（或标记为零收益但不把它们当独立新息），否则 \\(n\\) 被空洞放大。开盘前若干分钟单独网格，因为久期结构不同。</p><p><strong>Refresh time（刷新时间）。</strong> 多元已实现核常用：时钟只在<strong>所有</strong>成分都至少发生过一次新成交后前进一步。得到一条共同的不等间隔时间轴，每个时点上各资产都是「新鲜」的 previous-tick。代价是时钟被最不活跃的成分拖慢，活跃股的许多成交被扔掉。成分越多、越薄，refresh 越慢，接近低频。</p><p><strong>Hayashi–Yoshida 协方差。</strong> 不造共同网格。对 A 的每一段收益，与所有与之时间重叠的 B 段收益相乘再求和。重叠的定义使异步不再系统性地压低协方差。它对噪声仍敏感，常与预平均结合。对象是二次协变差，不是相关矩阵本身——还要各自的 \\(IV\\)。</p><p><strong>久期模型。</strong> Engle–Russell ACD：把成交间隔 \\(\\Delta t_i\\) 写成 \\(\\psi_i\\varepsilon_i\\)，\\(\\psi_i\\) 随过去久期自回归。它回答「下一笔何时来」，不是直接回答波动。把强度与价格变化联合（Engle ACD-GARCH 一类）才能把时间变形接到波动。成交量时钟、价格时钟是把点过程重参数化的另两条路。</p><h3 id="时间变形与波动" tabindex="-1">时间变形与波动 <a class="header-anchor" href="#时间变形与波动" aria-label="Permalink to &quot;时间变形与波动&quot;">​</a></h3><p>若交易强度与 \\(\\sigma_t\\) 正相关，事件时间里的收益更接近同方差，日历时间里则有明显的日内季节性。这是为什么有人在事件时钟上算 RV 或做短时预测。但事件时钟的「一天」长度随机，跨日比较要再映回日历。隔夜没有成交，事件时钟无法跨越，必须在日历上单独处理隔夜项。采样方案与 <a href="/quant/calendar-overnight">日历效应</a> 在日界处交接。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Previous-tick 造成 Epps 效应的机制：B 的价格停着，A 动了，乘积 \\(r^A r^B\\) 里 \\(r^B=0\\)，相关被摊薄。真实的共同跳若发生在两次成交之间，也会被拆到不同网格，共同变差流失。Refresh time 的机制是等到双方都更新，共同跳更可能落在同一增量里，但等待期间各自的特异变动被聚合，短时相关结构被平均。Hayashi–Yoshida 的机制是用重叠指示函数代替网格对齐，渐近上收回二次协变差。</p><p>ACD 的机制是把点过程的条件强度参数化，使久期的聚类（一笔之后很快又来一笔）可预测。它解释的是时间，不是价格；若把 ACD 强度当作「信息到达」，需要额外假定——PIN 类模型把到达写成泊松，是强度为常数的特例，ACD 允许强度时变。</p><p><span class="marginnote">成交量时钟把「间隔」从秒换成股。它不消除微观结构噪声，只改变噪声项里 \\(n\\) 的含义。等体积桶在闪崩时变短，朴素 RV 在该时钟上仍会被噪声和错价主导。时钟换了，清洗与异常规则不能省。</span></p><h3 id="与噪声修正的耦合" tabindex="-1">与噪声修正的耦合 <a class="header-anchor" href="#与噪声修正的耦合" aria-label="Permalink to &quot;与噪声修正的耦合&quot;">​</a></h3><p>TSRV、核、预平均的渐近通常写在等间隔或近似规则网格上。随机采样、与波动相关的交易时间，会改变收敛速度和偏差公式。实务上有两条路：先 previous-tick 到细网格再套核（承认插值偏差），或用为不规则采样写的估计量。不要把为等间隔推导的最优带宽，原封不动套到 refresh time 序列上——后者的「\\(n\\)」是刷新次数，不是秒数。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>成分极多的组合（指数、组合风险）无法对全部成分做 refresh，否则时钟停住。应对流动性分层：核心成分 refresh，其余用回归或 beta 映射。暗池与延迟报告会让「最后一笔」并不是当时可成交的最后一笔，previous-tick 的因果性只相对于你的磁带，不是相对于市场。</p><p>不要用线性插值做回测填值。不要把 Tick 数据里同一毫秒的多笔当成等间隔的多次采样——应先按 <a href="/quant/tick-cleaning">清洗规则</a> 合并事件。不要在涨跌停一侧没有成交时仍用过时价格填全日网格，那会制造长串零收益，核会把它们读成极强的噪声相关。期货与现货对时还要处理不同的会话与日历。</p><p><span class="marginnote">事件时间对预测下一口可能更齐整，对向监管或会计报告日波动则必须映回日历。两套时钟可以并存：盘中风控走成交量或成交笔数，日终风险走日历 RV 加隔夜。切换时钟时同步切换阈值，否则「三倍波动」的告警会在开盘脉冲里被事件时钟误触发。</span></p>',26)),(e(),l(h,null,{default:r(()=>[E(t,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20PP%5B%22%E7%82%B9%E8%BF%87%E7%A8%8B%3A%20%E6%88%90%E4%BA%A4%E9%9A%8F%E6%9C%BA%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20CAL%5B%22%E6%97%A5%E5%8E%86%E7%BD%91%E6%A0%BC%20%2B%20previous-tick%22%5D%0A%20%20PP%20--%3E%20EVT%5B%22%E4%BA%8B%E4%BB%B6%20%2F%20%E6%88%90%E4%BA%A4%E9%87%8F%E6%97%B6%E9%92%9F%22%5D%0A%20%20PP%20--%3E%20RT%5B%22%E5%A4%9A%E5%85%83%20refresh%20time%22%5D%0A%20%20PP%20--%3E%20HY%5B%22Hayashi%E2%80%93Yoshida%20%E9%87%8D%E5%8F%A0%E4%B9%98%E7%A7%AF%22%5D%0A%20%20CAL%20--%3E%20EPPS%5B%22%E8%BF%87%E6%97%B6%E4%BB%B7%E6%A0%BC%20%E2%86%92%20Epps%20%E7%9B%B8%E5%85%B3%E5%81%8F%E4%BD%8E%22%5D%0A%20%20RT%20--%3E%20SLOW%5B%22%E8%A2%AB%E6%9C%80%E8%96%84%E6%88%90%E5%88%86%E6%8B%96%E6%85%A2%22%5D%0A%20%20HY%20--%3E%20QV%5B%22%E4%BA%8C%E6%AC%A1%E5%8D%8F%E5%8F%98%E5%B7%AE%22%5D%0A%20%20EVT%20--%3E%20ACD%5B%22ACD%20%E4%B9%85%E6%9C%9F%20%2F%20%E5%BC%BA%E5%BA%A6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>高频观测是不等间隔点过程；等间隔序列是采样方案的产物，会改变噪声与协方差。</li><li>Previous-tick 因果但制造过时价格与 Epps 效应；线性插值前视。Refresh time 换共同新鲜时钟，被薄成分拖慢。</li><li>Hayashi–Yoshida 用重叠乘积估协变差，避开网格；ACD 为久期建模，不自动给出波动。</li><li>时钟选择与噪声修正、隔夜处理耦合；带宽与 \\(n\\) 必须按实际网格重定义。</li><li>回测禁止未来成交插值；停牌与涨跌停的空洞不能当普通零收益。</li><li>出处：Engle and Russell, <em>Autoregressive Conditional Duration</em>, Econometrica 1998；Hayashi and Yoshida 不同步协方差；refresh time 见 Barndorff-Nielsen, Hansen, Lunde, Shephard 多元已实现核实务。</li></ul>',2))])}const D=s(d,[["render",A]]);export{g as __pageData,D as default};
